const plannedSceneIds=[...new Set((scenePlan.match(/\bSC\d{3,}\b/g)||[]))];if(!plannedSceneIds.length)throw Error('Kế hoạch cảnh chưa có mã cảnh SC001… nên không thể kiểm tra độ bao phủ an toàn. Hãy tạo lại kịch bản.');
