normalizeSceneOrder();
const invalidSceneLines=d.danh_sach.map((line,index)=>({line:index+1,id:String(line.scene_id||'').trim()})).filter(x=>!x.id||!sceneOrder.has(x.id));if(invalidSceneLines.length)throw Error('Có lượt thoại thiếu scene_id hoặc dùng mã cảnh ngoài kế hoạch ở lượt '+invalidSceneLines.map(x=>x.line+' ('+(x.id||'trống')+')').join(', ')+'. Không thể kiểm toán tính liên tục an toàn.');
/* Independent semantic speaker audit: review dialogue in context, in small scene batches. */
